import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { SUPABASE_URL, SUPABASE_ANON_KEY } from './supabase-config.js';
const READY=Boolean(SUPABASE_URL&&SUPABASE_ANON_KEY&&SUPABASE_URL.includes('supabase.co'));
const supabase=READY?createClient(SUPABASE_URL,SUPABASE_ANON_KEY):null; const $=id=>document.getElementById(id); const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); let session=null;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.admin-tab').forEach(x=>x.classList.add('hidden'));$('tab-'+b.dataset.tab).classList.remove('hidden');document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));});
$('loginForm').onsubmit=async e=>{e.preventDefault();if(!READY){$('loginMsg').textContent='Supabase n’est pas configuré.';return;}const {data,error}=await supabase.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error){$('loginMsg').textContent=error.message;return;}session=data.session;await boot();};
async function boot(){const {data:admin}=await supabase.from('admin_users').select('user_id').eq('user_id',session.user.id).maybeSingle();if(!admin){$('loginMsg').textContent='Ce compte n’est pas autorisé comme administrateur.';await supabase.auth.signOut();return;}$('adminLogin').classList.add('hidden');$('dashboard').classList.remove('hidden');$('adminState').textContent='🛡️ '+session.user.email;await Promise.all([loadUsers(),loadQuestions(),loadAIs(),loadStats()]);}
async function loadUsers(){const el=$('tab-users');const [c,m]=await Promise.all([supabase.from('chat_conversations').select('user_id'),supabase.from('chat_messages').select('user_id')]);const ids=[...new Set([...(c.data||[]).map(x=>x.user_id),...(m.data||[]).map(x=>x.user_id)])];el.innerHTML='<div class="panel"><div class="eyebrow">COMPTES</div><h2>Utilisateurs actifs</h2><p class="small-note">Les comptes sont gérés par Supabase Auth.</p>'+ids.map(id=>`<div class="notice-card"><strong>${esc(id)}</strong><span>Utilisateur schat+</span></div>`).join('')+(ids.length?'':'<div class="empty-state">Aucun utilisateur avec une conversation.</div>')+'</div>';}
async function loadQuestions(){const el=$('tab-questions');const {data,error}=await supabase.from('chat_messages').select('id,conversation_id,user_id,role,content,created_at').eq('role','user').order('created_at',{ascending:false});const rows=error?[]:(data||[]);el.innerHTML='<div class="panel"><div class="eyebrow">MODÉRATION</div><h2>Questions</h2>'+rows.map(q=>`<div class="notice-card"><div><strong>${esc(q.content)}</strong><div class="small-note">${esc(q.user_id)} · ${new Date(q.created_at).toLocaleString('fr-CA')}</div></div><button class="secondary-btn" data-del-q="${q.id}">Supprimer</button></div>`).join('')+'</div>';el.querySelectorAll('[data-del-q]').forEach(b=>b.onclick=async()=>{await supabase.from('chat_messages').delete().eq('id',b.dataset.delQ);loadQuestions();});}
async function loadAIs(){const el=$('tab-ais');const {data,error}=await supabase.from('ai_agents').select('*').order('created_at');const rows=error?[]:(data||[]);el.innerHTML='<div class="panel"><div class="eyebrow">MODÈLES</div><h2>IA disponibles</h2><p class="small-note">Active/désactive les IA et modifie leur modèle.</p>'+rows.map(a=>`<div class="notice-card"><div><strong>🤖 ${esc(a.name)}</strong><div class="small-note">${esc(a.model)}</div></div><button class="primary-btn" data-ai="${a.id}">${a.enabled?'Désactiver':'Activer'}</button></div>`).join('')+'<form id="addAiForm" class="notice-card" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><strong>➕ Ajouter une IA</strong><input id="newAiName" maxlength="80" placeholder="Nom de l’IA" required><input id="newAiModel" maxlength="120" placeholder="Modèle" required><button class="primary-btn" type="submit">Ajouter</button></form></div>';el.querySelectorAll('[data-ai]').forEach(b=>b.onclick=async()=>{const a=rows.find(x=>String(x.id)===b.dataset.ai);if(!a)return;const {error}=await supabase.from('ai_agents').update({enabled:!a.enabled,updated_at:new Date().toISOString()}).eq('id',a.id);if(error)alert(error.message);else loadAIs();});$('addAiForm').onsubmit=async e=>{e.preventDefault();const name=$('newAiName').value.trim(),model=$('newAiModel').value.trim();const {error}=await supabase.from('ai_agents').insert({name,model,enabled:true,created_by:session.user.id});if(error)alert(error.message);else{e.target.reset();loadAIs();}};}
async function loadStats(){const [q,u,a]=await Promise.all([supabase.from('chat_messages').select('id',{count:'exact',head:true}).eq('role','user'),supabase.from('admin_users').select('user_id',{count:'exact',head:true}),supabase.from('chat_messages').select('id',{count:'exact',head:true}).eq('role','assistant')]);$('tab-stats').innerHTML='<div class="panel"><div class="eyebrow">APERÇU</div><h2>Statistiques</h2><div class="cards-grid"><div class="notice-card"><strong>Questions</strong><span>'+(q.count||0)+'</span></div><div class="notice-card"><strong>Admins</strong><span>'+(u.count||0)+'</span></div><div class="notice-card"><strong>Réponses IA</strong><span>'+(a.count||0)+'</span></div></div></div>';}
if(READY)supabase.auth.getSession().then(r=>{session=r.data.session;if(session)boot();});

import { createClient } from '@supabase/supabase-js';
import projectContext from './project-context.json' with { type: 'json' };

function json(res, status, body) {
  res.status(status).json(body);
}

function buildContext(live) {
  const fileText = projectContext.files
    .map(f => `FILE: ${f.path}\n${f.content}`)
    .join('\n\n---\n\n');

  const safeLive = {
    ai_agents: live.ai_agents || [],
    cards: live.cards || [],
    reservations: live.reservations || [],
    chat_conversations_count: live.chat_conversations_count || 0,
    chat_messages_count: live.chat_messages_count || 0
  };

  return `Tu es ChatGPT Admin de schat+.
Tu connais ce projet et tu dois aider l'administrateur à le maintenir.
Tu dois répondre en français.
Tu peux analyser les fichiers du projet et les données Supabase fournies ci-dessous.
Ne révèle jamais de secrets, clés API, mots de passe ou tokens.
Quand l'administrateur demande une modification, explique précisément les fichiers concernés et fournis une proposition structurée. N'affirme pas qu'une modification de fichier a été appliquée si elle ne l'est pas.

=== ETAT SUPABASE ===
${JSON.stringify(safeLive, null, 2)}

=== FICHIERS DU PROJET ===
${fileText}`;
}

function extractText(data) {
  if (typeof data.output_text === 'string' && data.output_text) return data.output_text;
  return (data.output || [])
    .flatMap(item => item.content || [])
    .map(part => part.text || '')
    .filter(Boolean)
    .join('\n')
    .trim();
}

export default async function handler(req, res) {
  if (req.method !== 'POST') return json(res, 405, { error: 'Méthode non autorisée' });

  const auth = req.headers.authorization || '';
  if (!auth.startsWith('Bearer ')) return json(res, 401, { error: 'Connexion requise.' });
  if (!process.env.SUPABASE_URL || !process.env.SUPABASE_ANON_KEY) return json(res, 500, { error: 'Supabase serveur non configuré.' });
  if (!process.env.OPENAI_API_KEY) return json(res, 503, { error: 'OPENAI_API_KEY n’est pas configurée sur Vercel.' });

  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_ANON_KEY, {
    global: { headers: { Authorization: auth } }
  });

  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) return json(res, 401, { error: 'Session invalide.' });

  const { data: admin, error: adminError } = await supabase
    .from('admin_users')
    .select('user_id')
    .eq('user_id', user.id)
    .maybeSingle();
  if (adminError) return json(res, 500, { error: 'Impossible de vérifier les droits admin.' });
  if (!admin) return json(res, 403, { error: 'Accès réservé à l’administrateur.' });

  const message = String(req.body?.message || '').trim();
  if (!message) return json(res, 400, { error: 'message est requis.' });
  if (message.length > 8000) return json(res, 400, { error: 'Message trop long.' });

  const [agents, cards, reservations, convs, msgs] = await Promise.all([
    supabase.from('ai_agents').select('id,name,description,model,enabled,created_at,updated_at').order('created_at'),
    supabase.from('cards').select('id,name,price,rarity,stock,card_number,description,status,created_at').order('created_at', { ascending: false }).limit(100),
    supabase.from('reservations').select('id,product_id,buyer_id,buyer_name,buyer_phone,status,created_at,archived').order('created_at', { ascending: false }).limit(100),
    supabase.from('chat_conversations').select('id', { count: 'exact', head: true }),
    supabase.from('chat_messages').select('id', { count: 'exact', head: true })
  ]);

  const context = buildContext({
    ai_agents: agents.data || [],
    cards: cards.data || [],
    reservations: reservations.data || [],
    chat_conversations_count: convs.count || 0,
    chat_messages_count: msgs.count || 0
  });

  const response = await fetch('https://api.openai.com/v1/responses', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`
    },
    body: JSON.stringify({
      model: process.env.OPENAI_MODEL || 'gpt-5-mini',
      input: [
        { role: 'system', content: [{ type: 'input_text', text: context }] },
        { role: 'user', content: [{ type: 'input_text', text: message }] }
      ]
    })
  });

  const data = await response.json().catch(() => ({}));
  if (!response.ok) return json(res, 502, { error: data?.error?.message || 'Erreur OpenAI.' });

  return json(res, 200, {
    answer: extractText(data) || 'Je n’ai pas reçu de réponse exploitable.',
    mode: 'admin-analysis',
    note: 'Les modifications de fichiers sont proposées ici; leur application permanente nécessite le pont de déploiement/source du projet.'
  });
}

import { createClient } from '@supabase/supabase-js';

export default async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'Méthode non autorisée' });
  const auth = req.headers.authorization || '';
  if (!auth.startsWith('Bearer ')) return res.status(401).json({ error: 'Connexion requise.' });
  if (!process.env.SUPABASE_URL || !process.env.SUPABASE_ANON_KEY) return res.status(500).json({ error: 'Supabase serveur non configuré.' });
  const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_ANON_KEY, { global: { headers: { Authorization: auth } } });
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError || !user) return res.status(401).json({ error: 'Session invalide.' });
  const { ai, question, agent_id } = req.body || {};
  if (!ai || !question) return res.status(400).json({ error: 'ai et question sont requis' });
  const { data: agent } = agent_id ? await supabase.from('ai_agents').select('id,name,system_prompt,model,enabled').eq('id',agent_id).maybeSingle() : await supabase.from('ai_agents').select('id,name,system_prompt,model,enabled').eq('name',ai).maybeSingle();
  if (!agent || !agent.enabled) return res.status(403).json({ error: `L’IA ${ai} est désactivée.` });
  const prompt = `${agent.system_prompt || 'Réponds en français, clairement et utilement.'}\n\nQuestion de l'utilisateur :\n${question}`;
  try {
    if (agent.name === 'ChatGPT' && process.env.OPENAI_API_KEY) {
      const r = await fetch('https://api.openai.com/v1/responses', { method:'POST', headers:{'Content-Type':'application/json',Authorization:`Bearer ${process.env.OPENAI_API_KEY}`}, body:JSON.stringify({model:agent.model||process.env.OPENAI_MODEL||'gpt-5-mini',input:prompt}) });
      const data=await r.json(); if(!r.ok)return res.status(502).json({error:data?.error?.message||'Erreur OpenAI'}); return res.json({answer:data.output_text||'Aucune réponse reçue.'});
    }
    if (agent.name === 'Claude' && process.env.ANTHROPIC_API_KEY) {
      const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json','x-api-key':process.env.ANTHROPIC_API_KEY,'anthropic-version':'2023-06-01'},body:JSON.stringify({model:agent.model||process.env.ANTHROPIC_MODEL||'claude-sonnet-4-5',max_tokens:1200,messages:[{role:'user',content:prompt}]})});
      const data=await r.json(); if(!r.ok)return res.status(502).json({error:data?.error?.message||'Erreur Anthropic'}); return res.json({answer:(data.content||[]).map(x=>x.text||'').join('\n')||'Aucune réponse reçue.'});
    }
    if (agent.name === 'Gemini' && process.env.GEMINI_API_KEY) {
      const model=agent.model||process.env.GEMINI_MODEL||'gemini-2.5-flash'; const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(process.env.GEMINI_API_KEY)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({contents:[{parts:[{text:prompt}]}]})}); const data=await r.json(); if(!r.ok)return res.status(502).json({error:data?.error?.message||'Erreur Gemini'}); return res.json({answer:data?.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('\n')||'Aucune réponse reçue.'});
    }
    return res.status(503).json({ error: `L’API de ${agent.name} n’est pas encore configurée sur le serveur.` });
  } catch(e) { return res.status(500).json({error:'Erreur serveur IA'}); }
}

