// Exemple de point d'entrée serveur.
// À déployer sur un backend/Edge Function et à compléter avec les SDK des modèles.
// Les clés doivent rester dans les variables d'environnement.
import express from "express";
const app=express(); app.use(express.json());
app.post("/api/ai", async (req,res)=>{
  const {ai,question}=req.body||{};
  if(!ai||!question) return res.status(400).json({error:"ai et question sont requis"});
  // Branche ici le SDK correspondant. Ne renvoie jamais la clé API au navigateur.
  return res.json({answer:`Réponse serveur de démonstration pour ${ai} : ${question}`});
});
app.listen(process.env.PORT||3000,()=>console.log("schat+ AI API prête"));

import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { SUPABASE_URL, SUPABASE_ANON_KEY } from './supabase-config.js';

const READY = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY && SUPABASE_URL.includes('supabase.co') && !SUPABASE_URL.includes('TON-PROJET'));
const supabase = READY ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) : null;

const AI_DEFAULTS = [];
let ais = [], questions = [], answers = [];
let selectedQuestion = null, selectedAI = null, session = null;
let realtimeChannel = null;
const $=id=>document.getElementById(id);
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function setView(view){$('chatView').classList.toggle('hidden',view!=='chat');$('pokeplexView').classList.toggle('hidden',view!=='pokeplex');document.querySelectorAll('.menu-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('viewTitle').textContent=view==='pokeplex'?'Poképlx':'schat+';}
function renderAI(){const wrap=$('aiMenu');wrap.innerHTML='';const active=ais.filter(a=>a.enabled);if(!active.length){wrap.innerHTML='<div class="ai-empty">Aucune IA active</div>';return;}active.forEach(ai=>{const b=document.createElement('button');b.type='button';b.className='menu-item ai-button'+(selectedAI?.id===ai.id?' active':'');b.innerHTML='<span class="ai-dot"></span><span>'+escapeHtml(ai.name)+'</span><span class="ai-arrow">›</span>';b.onclick=()=>chooseAI(ai);wrap.appendChild(b);});}
function renderQuestions(){const list=$('questionsList');$('questionCount').textContent=questions.length;list.innerHTML='';if(!questions.length){list.innerHTML='<div class="empty-state">Aucune question pour le moment.</div>';return;}questions.forEach(q=>{const b=document.createElement('button');b.className='question-item'+(selectedQuestion?.id===q.id?' active':'');b.innerHTML='<strong>'+escapeHtml(q.text)+'</strong><small>'+new Date(q.created_at).toLocaleString('fr-CA')+'</small>';b.onclick=()=>{selectedQuestion=q;renderQuestions();showSavedAnswer();};list.appendChild(b);});}
function showSavedAnswer(){if(!selectedQuestion)return;const saved=answers.filter(a=>a.conversation_id===selectedQuestion.conversation_id&&a.role==='assistant');const current=selectedAI&&saved.find(a=>a.ai_name===selectedAI.name);if(current){$('responseTitle').textContent=selectedAI.name;$('selectedAiLabel').textContent='RÉPONSE';$('responseBox').textContent=current.content;$('answerStatus').className='status-dot ok';}else{$('responseTitle').textContent='Question sélectionnée';$('selectedAiLabel').textContent='CHOISIS UNE IA';$('responseBox').innerHTML='<div class="empty-response"><div class="big-icon">🤖</div><strong>Choisis une IA</strong><span>Utilise le menu de gauche pour répondre.</span></div>';}}
async function loadAIs(){if(!READY||!session)return;const {data,error}=await supabase.from('ai_agents').select('id,name,description,system_prompt,model,enabled').eq('enabled',true).order('created_at');if(!error)ais=(data||[]).map(a=>({...a,id:String(a.id)}));if(!selectedAI||!ais.some(a=>a.id===selectedAI.id))selectedAI=null;renderAI();}
async function loadQuestions(){if(!READY||!session){questions=[];answers=[];renderQuestions();return;}const {data:convs,error:cerr}=await supabase.from('chat_conversations').select('id,ai_agent_id,title,created_at,updated_at').eq('user_id',session.user.id).order('updated_at',{ascending:false});if(cerr){console.error(cerr);return;}const ids=(convs||[]).map(c=>c.id);let msgs=[];if(ids.length){const r=await supabase.from('chat_messages').select('id,conversation_id,user_id,role,content,created_at').in('conversation_id',ids).order('created_at',{ascending:true});if(!r.error)msgs=r.data||[];}const byConv=new Map();for(const m of msgs){if(!byConv.has(m.conversation_id))byConv.set(m.conversation_id,[]);byConv.get(m.conversation_id).push(m);}questions=[];answers=[];for(const c of convs||[]){const ms=byConv.get(c.id)||[];const q=ms.find(m=>m.role==='user');if(q)questions.push({id:q.id,conversation_id:c.id,text:q.content,created_at:q.created_at});for(const m of ms.filter(m=>m.role==='assistant')){const ai=ais.find(a=>a.id===c.ai_agent_id);answers.push({...m,ai_name:ai?.name||c.title||'IA'});}}renderQuestions();if(selectedQuestion)showSavedAnswer();}
async function addQuestion(text){if(!text.trim())return;if(!session){$('authGate').classList.remove('hidden');showAuthForm('login');return;}const qtext=text.trim();const {data,error}=await supabase.from('chat_conversations').insert({user_id:session.user.id,title:qtext.slice(0,80)}).select().single();if(error){alert('Impossible de créer la conversation : '+error.message);return;}const {data:msg,error:me}=await supabase.from('chat_messages').insert({conversation_id:data.id,user_id:session.user.id,role:'user',content:qtext}).select().single();if(me){alert('Impossible d’enregistrer la question : '+me.message);await supabase.from('chat_conversations').delete().eq('id',data.id);return;}$('questionInput').value='';await loadQuestions();selectedQuestion={id:msg.id,conversation_id:data.id,text:qtext,created_at:msg.created_at};renderQuestions();showSavedAnswer();}
async function chooseAI(ai){if(!selectedQuestion){$('responseBox').innerHTML='<div class="empty-response"><div class="big-icon">☝️</div><strong>Sélectionne d’abord une question</strong></div>';return;}if(!session){$('authGate').classList.remove('hidden');showAuthForm('login');return;}selectedAI=ai;renderAI();$('answerStatus').className='status-dot loading';$('responseTitle').textContent=ai.name;$('selectedAiLabel').textContent='GÉNÉRATION';$('responseBox').textContent='L’IA prépare sa réponse…';const existing=answers.find(a=>a.conversation_id===selectedQuestion.conversation_id&&a.ai_name===ai.name);if(existing){showSavedAnswer();return;}try{const headers={'Content-Type':'application/json',Authorization:`Bearer ${session.access_token}`};const r=await fetch('/api/ai',{method:'POST',headers,body:JSON.stringify({ai:ai.name,question:selectedQuestion.text,agent_id:ai.id})});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`Impossible d’obtenir une réponse de ${ai.name}.`);const {data:msg,error}=await supabase.from('chat_messages').insert({conversation_id:selectedQuestion.conversation_id,user_id:session.user.id,role:'assistant',content:data.answer}).select().single();if(error)throw new Error('Réponse reçue, mais impossible de la sauvegarder : '+error.message);answers.push({...msg,ai_name:ai.name});$('responseBox').textContent=data.answer;$('answerStatus').className='status-dot ok';$('selectedAiLabel').textContent='RÉPONSE';await supabase.from('chat_conversations').update({ai_agent_id:ai.id,updated_at:new Date().toISOString()}).eq('id',selectedQuestion.conversation_id);}catch(error){$('responseBox').textContent='⚠️ '+error.message;$('answerStatus').className='status-dot error';$('selectedAiLabel').textContent='ERREUR';}}
function showAuthForm(type){
  const register=type==='register';
  $('authForms').innerHTML=`<form class="auth-form" id="authForm">
    ${register?'<input id="authUsername" placeholder="Pseudo" required>':''}
    <input id="authEmail" type="email" placeholder="Email" required>
    <input id="authPassword" type="password" placeholder="Mot de passe" required>
    <button class="primary-btn" type="submit">${register?'Créer mon compte':'Se connecter'}</button>
    <div id="authMsg"></div></form>`;
  $('authForm').onsubmit=async e=>{e.preventDefault();const email=$('authEmail').value.trim(),password=$('authPassword').value;
    if(!READY){$('authMsg').textContent='Mode démo : configure Supabase pour activer les vrais comptes.';return;}
    let result;
    if(register){result=await supabase.auth.signUp({email,password,options:{data:{username:$('authUsername').value.trim()}}});}
    else result=await supabase.auth.signInWithPassword({email,password});
    $('authMsg').textContent=result.error?result.error.message:'Compte prêt !'; if(!result.error){await refreshSession();}
  };
}
let realtimeChannel=null;
function startRealtime(){
  if(!READY || !session) return;
  if(realtimeChannel) supabase.removeChannel(realtimeChannel);
  realtimeChannel=supabase.channel(`schat-user-${session.user.id}`)
    .on('postgres_changes',{event:'*',schema:'public',table:'questions',filter:`user_id=eq.${session.user.id}`},async()=>{await loadQuestions();})
    .on('postgres_changes',{event:'*',schema:'public',table:'answers'},async()=>{await loadQuestions();})
    .subscribe();
