// Copie ce fichier sous le nom supabase-config.js et remplace les valeurs.
export const SUPABASE_URL = 'https://TON-PROJET.supabase.co';
export const SUPABASE_ANON_KEY = 'TON_ANON_KEY';

const CACHE='schat-plus-v1';
const ASSETS=['./','./index.html','./styles.css','./app.js','./supabase-config.js','./manifest.webmanifest'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));
self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&e.request.url.startsWith(self.location.origin))e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request)));});

